def wrap(scene):
 s=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">{scene}</svg>'
 ET.fromstring(s)
 assert not re.search(r'<(?:script|image|text|foreignObject)|href=|onload=',s,re.I)
 return s

